// ============================================================
// Pulse Admin Audit Log Page
// Owned by Member B (Phase B4: Admin UI)
// Contract §5, §6:
//   - Route: /admin/audit (ADMIN only)
//   - GET /admin/audit?limit=100
//   - Displays immutable audit log generated by DB triggers & lib/audit.js
// ============================================================

import React, { useState, useEffect } from 'react';
import { api } from '../../api/client';
import { PageHeader, Card, Badge, Spinner, ErrorBox, EmptyState } from '../../components/ui';
import './admin.css';

export default function Audit() {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [limit, setLimit] = useState(100);
  const [search, setSearch] = useState('');
  const [actionFilter, setActionFilter] = useState('ALL');

  const loadAudit = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await api.get(`/admin/audit?limit=${limit}`);
      setLogs(Array.isArray(data) ? data : []);
    } catch (err) {
      console.warn('GET /admin/audit failed:', err);
      setError(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAudit();
  }, [limit]);

  // Extract unique actions for the filter dropdown
  const uniqueActions = Array.from(
    new Set(logs.map((l) => l.action).filter(Boolean))
  ).sort();

  // Filtered log entries
  const filteredLogs = logs.filter((entry) => {
    const matchesAction =
      actionFilter === 'ALL' || entry.action === actionFilter;

    const q = search.trim().toLowerCase();
    if (!q) return matchesAction;

    const actionMatch = entry.action && entry.action.toLowerCase().includes(q);
    const actorMatch =
      entry.actor_role && entry.actor_role.toLowerCase().includes(q);
    const entityMatch =
      entry.entity && entry.entity.toLowerCase().includes(q);
    const idMatch =
      (entry.entity_id && String(entry.entity_id).includes(q)) ||
      (entry.actor_id && String(entry.actor_id).includes(q));

    return matchesAction && (actionMatch || actorMatch || entityMatch || idMatch);
  });

  return (
    <div className="admin-page">
      <PageHeader
        title="Audit Trail"
        subtitle="Immutable security log recording administrative actions, database triggers, and lifecycle events"
        action={
          <button
            type="button"
            className="admin-btn admin-btn--secondary"
            onClick={loadAudit}
            disabled={loading}
          >
            Refresh Log
          </button>
        }
      />

      {error && !loading && (
        <ErrorBox message={error} onRetry={loadAudit} />
      )}

      <Card>
        {/* Filters and search toolbar */}
        <div className="admin-toolbar">
          <div className="admin-toolbar__left">
            <input
              type="text"
              className="admin-search-input"
              placeholder="Search by action, actor, entity ID..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />

            <select
              className="admin-search-input"
              style={{ minWidth: 180 }}
              value={actionFilter}
              onChange={(e) => setActionFilter(e.target.value)}
            >
              <option value="ALL">All Actions ({logs.length})</option>
              {uniqueActions.map((act) => (
                <option key={act} value={act}>
                  {act}
                </option>
              ))}
            </select>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <span style={{ fontSize: 13, color: 'var(--ink-muted)' }}>Show:</span>
            <select
              className="admin-search-input"
              style={{ minWidth: 90 }}
              value={limit}
              onChange={(e) => setLimit(Number(e.target.value))}
            >
              <option value={50}>50 rows</option>
              <option value={100}>100 rows</option>
              <option value={250}>250 rows</option>
            </select>
          </div>
        </div>

        {loading && <Spinner label="Loading audit log entries..." />}

        {!loading && logs.length === 0 && (
          <EmptyState title="No audit entries found">
            Audit events will be automatically recorded whenever requests, donations,
            or security states change.
          </EmptyState>
        )}

        {!loading && logs.length > 0 && filteredLogs.length === 0 && (
          <EmptyState title="No log entries match your filter">
            Try adjusting your search terms or selecting "All Actions".
          </EmptyState>
        )}

        {!loading && filteredLogs.length > 0 && (
          <div className="admin-table-wrapper">
            <table className="admin-table">
              <thead>
                <tr>
                  <th>#</th>
                  <th>Timestamp</th>
                  <th>Actor</th>
                  <th>Action</th>
                  <th>Target Entity</th>
                </tr>
              </thead>
              <tbody>
                {filteredLogs.map((entry) => (
                  <tr key={entry.log_id}>
                    <td>
                      <span style={{ color: 'var(--ink-subtle)' }}>#{entry.log_id}</span>
                    </td>
                    <td style={{ whiteSpace: 'nowrap' }}>
                      {entry.created_at
                        ? new Date(entry.created_at).toLocaleString()
                        : '—'}
                    </td>
                    <td>
                      <span className="admin-audit-actor">
                        <Badge
                          tone={
                            entry.actor_role === 'ADMIN'
                              ? 'ok'
                              : entry.actor_role === 'STAFF'
                              ? 'neutral'
                              : 'neutral'
                          }
                        >
                          {entry.actor_role || 'SYSTEM'}
                          {entry.actor_id ? ` #${entry.actor_id}` : ''}
                        </Badge>
                      </span>
                    </td>
                    <td>
                      <span className="admin-audit-action">{entry.action}</span>
                    </td>
                    <td>
                      {entry.entity ? (
                        <span>
                          <strong>{entry.entity}</strong>
                          {entry.entity_id != null ? ` #${entry.entity_id}` : ''}
                        </span>
                      ) : (
                        '—'
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
    </div>
  );
}
